[metadata] {"type": "create", "filePath": "/app/output/presentation.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks</title>

    <!-- Fonts: Syne (display), Outfit (body), JetBrains Mono (data) -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Outfit:wght@300;400;500;600;700&family=Syne:wght@600;700;800&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           =========================================== */
        :root {
            /* Colors */
            --bg-primary: #080c18;
            --bg-secondary: #0d1224;
            --bg-card: #111830;
            --bg-card-hover: #161e3a;
            --border-color: rgba(255, 255, 255, 0.06);
            --text-primary: #e8ecf4;
            --text-secondary: #8892a8;
            --text-dim: #5a6478;
            --accent: #00e5c8;
            --accent-glow: rgba(0, 229, 200, 0.15);

            /* Lab colors */
            --lab-openai: #10b981;
            --lab-google: #60a5fa;
            --lab-anthropic: #fbbf24;
            --lab-muse: #c084fc;

            /* Typography */
            --font-display: 'Syne', sans-serif;
            --font-body: 'Outfit', sans-serif;
            --font-mono: 'JetBrains Mono', monospace;
            --title-size: clamp(1.5rem, 5vw, 4rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(0.85rem, 2vw, 1.4rem);
            --body-size: clamp(0.7rem, 1.3vw, 1rem);
            --small-size: clamp(0.6rem, 0.9vw, 0.8rem);
            --data-size: clamp(0.55rem, 0.85vw, 0.78rem);

            /* Spacing */
            --slide-padding: clamp(1rem, 4vw, 4rem);
            --content-gap: clamp(0.5rem, 2vw, 2rem);
            --element-gap: clamp(0.25rem, 1vw, 1rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }
        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }
        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }
        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* ===========================================
           RESPONSIVE BREAKPOINTS
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root {
                --title-size: clamp(1.25rem, 7vw, 2.5rem);
            }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        /* ===========================================
           BACKGROUND EFFECTS
           =========================================== */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }

        .slide::after {
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(ellipse at 15% 85%, rgba(0, 229, 200, 0.06) 0%, transparent 50%),
                radial-gradient(ellipse at 85% 15%, rgba(96, 165, 250, 0.05) 0%, transparent 50%);
            pointer-events: none;
            z-index: 0;
        }

        .slide > * { position: relative; z-index: 1; }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0; left: 0;
            height: 3px;
            background: var(--accent);
            z-index: 1000;
            transition: width 0.3s ease;
            box-shadow: 0 0 10px var(--accent-glow);
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 1.5vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 1000;
        }
        .nav-dot {
            width: 8px; height: 8px;
            border-radius: 50%;
            background: var(--text-dim);
            border: none;
            cursor: pointer;
            transition: all 0.3s ease;
            padding: 0;
        }
        .nav-dot.active {
            background: var(--accent);
            box-shadow: 0 0 8px var(--accent-glow);
            transform: scale(1.3);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }
        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.12s; }
        .reveal:nth-child(3) { transition-delay: 0.19s; }
        .reveal:nth-child(4) { transition-delay: 0.26s; }
        .reveal:nth-child(5) { transition-delay: 0.33s; }
        .reveal:nth-child(6) { transition-delay: 0.40s; }
        .reveal:nth-child(7) { transition-delay: 0.47s; }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.92);
            transition: opacity 0.6s var(--ease-out-expo),
                        transform 0.6s var(--ease-out-expo);
        }
        .slide.visible .reveal-scale {
            opacity: 1;
            transform: scale(1);
        }

        /* Bar animation */
        .bar-fill {
            width: 0;
            transition: width 1s var(--ease-out-expo);
        }
        .slide.visible .bar-fill {
            /* Width set inline per bar */
        }

        /* ===========================================
           SLIDE-SPECIFIC: TITLE SLIDE
           =========================================== */
        .title-slide {
            justify-content: center;
            align-items: center;
            text-align: center;
        }
        .title-slide .title-main {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: var(--title-size);
            line-height: 1.1;
            letter-spacing: -0.02em;
            margin-bottom: clamp(0.5rem, 2vh, 1.5rem);
            background: linear-gradient(135deg, #fff 0%, var(--accent) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }
        .title-slide .title-sub {
            font-family: var(--font-body);
            font-weight: 300;
            font-size: var(--h3-size);
            color: var(--text-secondary);
            max-width: min(80vw, 700px);
            line-height: 1.5;
        }
        .title-slide .title-tag {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent);
            margin-top: clamp(0.5rem, 2vh, 1.5rem);
            letter-spacing: 0.15em;
            text-transform: uppercase;
        }
        .title-slide .domain-pills {
            display: flex;
            gap: clamp(0.3rem, 1vw, 0.8rem);
            justify-content: center;
            margin-top: clamp(0.5rem, 2vh, 1.2rem);
            flex-wrap: wrap;
        }
        .domain-pill {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            padding: clamp(0.2rem, 0.5vh, 0.4rem) clamp(0.5rem, 1vw, 1rem);
            border-radius: 20px;
            border: 1px solid var(--border-color);
            background: rgba(255,255,255,0.03);
            color: var(--text-secondary);
        }

        /* ===========================================
           SLIDE HEADER (used on content slides)
           =========================================== */
        .slide-header {
            margin-bottom: clamp(0.5rem, 1.5vh, 1.5rem);
        }
        .slide-header h2 {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--h2-size);
            line-height: 1.2;
            color: var(--text-primary);
        }
        .slide-header .slide-subtitle {
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-top: clamp(0.2rem, 0.5vh, 0.5rem);
            font-weight: 300;
        }

        /* ===========================================
           LAB BADGES
           =========================================== */
        .lab-badge {
            display: inline-block;
            font-family: var(--font-mono);
            font-size: clamp(0.5rem, 0.7vw, 0.7rem);
            font-weight: 600;
            padding: 2px 6px;
            border-radius: 3px;
            letter-spacing: 0.05em;
            text-transform: uppercase;
        }
        .lab-openai { background: rgba(16, 185, 129, 0.15); color: var(--lab-openai); }
        .lab-google { background: rgba(96, 165, 250, 0.15); color: var(--lab-google); }
        .lab-anthropic { background: rgba(251, 191, 36, 0.15); color: var(--lab-anthropic); }
        .lab-muse { background: rgba(192, 132, 252, 0.15); color: var(--lab-muse); }

        /* ===========================================
           DATA TABLE STYLES
           =========================================== */
        .data-table {
            width: 100%;
            border-collapse: collapse;
            font-family: var(--font-mono);
            font-size: var(--data-size);
        }
        .data-table th {
            text-align: left;
            font-weight: 600;
            color: var(--text-secondary);
            padding: clamp(0.25rem, 0.5vh, 0.5rem) clamp(0.3rem, 0.8vw, 0.8rem);
            border-bottom: 1px solid var(--border-color);
            font-size: clamp(0.5rem, 0.75vw, 0.72rem);
            text-transform: uppercase;
            letter-spacing: 0.08em;
        }
        .data-table td {
            padding: clamp(0.2rem, 0.4vh, 0.4rem) clamp(0.3rem, 0.8vw, 0.8rem);
            border-bottom: 1px solid rgba(255,255,255,0.03);
            color: var(--text-primary);
            white-space: nowrap;
        }
        .data-table tr:hover {
            background: rgba(255,255,255,0.02);
        }
        .score-highlight {
            font-weight: 700;
            color: var(--accent);
        }

        /* ===========================================
           BAR CHART (Horizontal)
           =========================================== */
        .hbar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.6vh, 0.6rem);
        }
        .hbar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.5vw, 0.6rem);
        }
        .hbar-label {
            font-family: var(--font-mono);
            font-size: var(--data-size);
            color: var(--text-secondary);
            width: clamp(6rem, 15vw, 14rem);
            text-align: right;
            flex-shrink: 0;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .hbar-track {
            flex: 1;
            height: clamp(16px, 2.2vh, 24px);
            background: rgba(255,255,255,0.04);
            border-radius: 3px;
            overflow: hidden;
            position: relative;
        }
        .hbar-fill {
            height: 100%;
            border-radius: 3px;
            transition: width 1.2s var(--ease-out-expo);
            position: relative;
        }
        .hbar-value {
            font-family: var(--font-mono);
            font-size: var(--data-size);
            font-weight: 600;
            color: var(--text-primary);
            width: clamp(2.5rem, 4vw, 4rem);
            text-align: left;
            flex-shrink: 0;
        }

        /* ===========================================
           DOMAIN CARDS (Slide 2)
           =========================================== */
        .domain-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: clamp(0.4rem, 1vw, 1rem);
        }
        @media (max-width: 800px) {
            .domain-grid { grid-template-columns: repeat(2, 1fr); }
        }
        .domain-card {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.5vh, 1.2rem) clamp(0.5rem, 1vw, 1rem);
            transition: border-color 0.3s ease, background 0.3s ease;
        }
        .domain-card:hover {
            border-color: rgba(255,255,255,0.12);
            background: var(--bg-card-hover);
        }
