    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isScrolling = false;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupProgressBar();
                this.setupNavDots();
                this.setupWheelNav();
                this.animateBars();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const idx = Array.from(this.slides).indexOf(entry.target);
                            this.currentSlide = idx;
                            this.updateProgress();
                            this.updateNavDots();
                            this.animateBarsInSlide(entry.target);
                        }
                    });
                }, { threshold: 0.5 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'PageDown' || e.key === ' ') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowUp' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    }
                });
            }

            setupTouchNav() {
                let touchStartY = 0;
                document.addEventListener('touchstart', (e) => {
                    touchStartY = e.touches[0].clientY;
                }, { passive: true });
                document.addEventListener('touchend', (e) => {
                    const diff = touchStartY - e.changedTouches[0].clientY;
                    if (Math.abs(diff) > 50) {
                        this.goToSlide(this.currentSlide + (diff > 0 ? 1 : -1));
                    }
                }, { passive: true });
            }

            setupWheelNav() {
                document.addEventListener('wheel', (e) => {
                    if (this.isScrolling) return;
                    this.isScrolling = true;
                    const direction = e.deltaY > 0 ? 1 : -1;
                    this.goToSlide(this.currentSlide + direction);
                    setTimeout(() => { this.isScrolling = false; }, 800);
                }, { passive: true });
            }

            setupProgressBar() {
                this.progressBar = document.getElementById('progressBar');
            }

            setupNavDots() {
                const navDots = document.getElementById('navDots');
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(i));
                    dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
                    navDots.appendChild(dot);
                });
                this.dots = navDots.querySelectorAll('.nav-dot');
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.slides.length) * 100;
                this.progressBar.style.width = progress + '%';
            }

            updateNavDots() {
                this.dots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === this.currentSlide);
                });
            }

            goToSlide(index) {
                if (index < 0 || index >= this.slides.length) return;
